// Помощники автосохранения черновика /addbusiness (#0c6087). ПРОД, ничего не пишем:
// - POST rest/v1/business (создание черновика на 1→2) — fulfill 201 локально строкой с фиктивным id;
// - PATCH business?id=eq.<фиктивный id> — тело запоминается, ответ по ctl.patchStatus (200 / 500) локально;
// - GET business?id=eq.<фиктивный id> — запомненная строка;
// - POST auth/v1/token (продление сессии Supabase) пропускается — это не запись данных;
// - все прочие не-GET — abort. ctl.passed — не-GET, которые всё-таки дошли до сервера (должно быть пусто).
import { expect, Page, Request, APIRequestContext } from '@playwright/test';

export const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];
export const LOAD = { timeout: 20_000 };
export const NEXT = 'שלב הבא';
export const BACK = 'חזרה';
export const DRAFT_ERR = 'לא הצלחנו לשמור את הטיוטה, אך תוכל להמשיך בתהליך';
export const CONSOLE_ERR = '[AddBusiness] failed to update draft';
export const FREE = 'חבילה 1 – הכרות חינם';
export const CATEGORY = 'בתי קפה ומסעדות';
/** Фиктивный id черновика — такой записи на сервере нет. */
export const FAKE_ID = '00000000-0000-4000-8000-000000000a01';

const isBusiness = (url: string) => /\/rest\/v1\/business(\?|$)/.test(url);
const isOwnRow = (url: string) => isBusiness(url) && url.includes(`id=eq.${FAKE_ID}`);
const isTokenRefresh = (url: string, m: string) => m === 'POST' && /\/auth\/v1\/token/.test(url);

export type Body = Record<string, unknown>;
export type DraftCtl = {
  patchStatus: number;
  posts: Body[];
  patches: Body[];
  row: Body | null;
  passed: string[];
  /** apikey и origin Supabase — из перехваченного запроса, для чтения схемы (GET). */
  supabase: { origin: string; apikey: string } | null;
  consoleErrors: string[];
};

function asObjectAccept(req: Request) {
  return (req.headers()['accept'] || '').includes('vnd.pgrst.object');
}

export async function interceptDraft(page: Page): Promise<DraftCtl> {
  const ctl: DraftCtl = { patchStatus: 200, posts: [], patches: [], row: null, passed: [], supabase: null, consoleErrors: [] };

  page.on('console', (msg) => {
    if (msg.text().includes(CONSOLE_ERR)) ctl.consoleErrors.push(msg.text());
  });

  await page.route('**/*', async (route) => {
    const req = route.request();
    const m = req.method();
    const url = req.url();
    if (isBusiness(url) && !ctl.supabase && req.headers()['apikey']) {
      ctl.supabase = { origin: new URL(url).origin, apikey: req.headers()['apikey'] };
    }
    if (m === 'GET' && isOwnRow(url) && ctl.row) {
      const body = asObjectAccept(req) ? ctl.row : [ctl.row];
      return route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(body) });
    }
    if (SAFE_METHODS.includes(m) || isTokenRefresh(url, m)) return route.fallback();
    let body: Body = {};
    try { body = (req.postDataJSON() as Body) ?? {}; } catch { /* пусто */ }
    if (Array.isArray(body)) body = (body[0] as Body) ?? {};
    if (m === 'POST' && isBusiness(url)) {
      ctl.posts.push(body);
      ctl.row = { ...body, id: FAKE_ID };
      const out = asObjectAccept(req) ? ctl.row : [ctl.row];
      return route.fulfill({ status: 201, contentType: 'application/json', body: JSON.stringify(out) });
    }
    if (m === 'PATCH' && isOwnRow(url)) {
      ctl.patches.push(body);
      if (ctl.patchStatus >= 400) {
        return route.fulfill({
          status: ctl.patchStatus,
          contentType: 'application/json',
          body: JSON.stringify({ code: 'XX000', message: 'QA-AUTO simulated server error', details: null, hint: null }),
        });
      }
      ctl.row = { ...(ctl.row ?? { id: FAKE_ID }), ...body };
      const out = asObjectAccept(req) ? ctl.row : [ctl.row];
      return route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(out) });
    }
    return route.abort('blockedbyclient');
  });

  page.on('requestfinished', (r: Request) => {
    const m = r.method();
    const url = r.url();
    if (SAFE_METHODS.includes(m) || isTokenRefresh(url, m)) return;
    if ((m === 'POST' && isBusiness(url)) || (m === 'PATCH' && isOwnRow(url))) return; // отвечены локально
    ctl.passed.push(`${m} ${url}`);
  });
  return ctl;
}

/** Шаг 1 (минимальные значения QA-AUTO) → «שלב הבא» → шаг 2 «נתונים נוספים». */
export async function fillStep1AndNext(page: Page, ctl: DraftCtl) {
  await page.goto('/addbusiness');
  await page.getByPlaceholder('יופיע ככותרת של המודעה שלך').fill('QA-AUTO draft');
  await page.getByPlaceholder('תרשום את תיאור העסק שלך, חשוב מאוד יעזור לך למכור!').fill('QA-AUTO בדיקה אוטומטית — לא נשמר בשרת.');
  await page.getByPlaceholder('טלפון ליצירת קשר*').fill('0500000000');
  await page.getByPlaceholder('מחיר').fill('100000');
  await page.getByRole('combobox').filter({ hasText: 'קטגוריה' }).click();
  await page.getByRole('option', { name: CATEGORY, exact: true }).click();
  await page.getByRole('button', { name: NEXT }).click();
  await expect(page.getByText('משך פעילות העסק (שנים/חודשים)'), 'шаг 2 «נתונים נוספים»').toBeVisible(LOAD);
  await expect.poll(() => ctl.posts.length, { message: 'черновик создан (POST business, отвечен локально)', ...LOAD }).toBe(1);
}

/** Шаг 2 с пустыми числовыми полями → шаг 3. */
export async function step2EmptyNext(page: Page) {
  const numeric = page.locator('input[type="number"], input[inputmode="numeric"], input[inputmode="decimal"]');
  for (const el of await numeric.all()) {
    if (await el.isVisible()) await expect(el, 'числовое поле шага 2 пустое').toHaveValue('');
  }
  await page.getByRole('button', { name: NEXT }).click();
  await expect(page.getByRole('heading', { name: 'העלאת תמונות', exact: true }), 'шаг 3 — фото').toBeVisible(LOAD);
}

/** Нажать «שלב הבא» и дождаться PATCH черновика (ответ локальный). */
export async function nextWithPatch(page: Page, ctl: DraftCtl, label: string) {
  const before = ctl.patches.length;
  await page.getByRole('button', { name: NEXT }).click();
  await expect.poll(() => ctl.patches.length, { message: `${label}: ушёл PATCH черновика`, ...LOAD }).toBeGreaterThan(before);
}

/**
 * Числовые колонки business из схемы PostgREST (GET /rest/v1/ — OpenAPI, только чтение).
 * Если схема недоступна — null (тогда числовые поля определяются по имени, см. NUMERIC_NAME).
 */
export async function numericColumns(request: APIRequestContext, ctl: DraftCtl): Promise<Set<string> | null> {
  if (!ctl.supabase) return null;
  const res = await request.get(`${ctl.supabase.origin}/rest/v1/`, {
    headers: { apikey: ctl.supabase.apikey, Accept: 'application/openapi+json' },
  }).catch(() => null);
  if (!res || !res.ok()) return null;
  const json = await res.json().catch(() => null);
  const props = json?.definitions?.business?.properties as Record<string, { type?: string; format?: string }> | undefined;
  if (!props) return null;
  const nums = Object.entries(props)
    .filter(([, p]) => p.type === 'number' || p.type === 'integer' || /double|numeric|integer|bigint|real|smallint/.test(p.format || ''))
    .map(([k]) => k);
  return new Set(nums);
}

/** Запасной признак числового поля по имени колонки (если схема PostgREST недоступна). */
export const NUMERIC_NAME = /revenue|turnover|profit|income|expense|cost|employee|worker|rent|area|size|sqm|meter|price|amount|year|month|count|num_employees|salary|seats|capacity/i;

/** Числовые поля тела со значением "" — их быть не должно («מה רצוי»: «שדה ריק נשלח כ-null / לא נשלח»). */
export function emptyStringFields(body: Body, numeric: Set<string> | null): string[] {
  return Object.entries(body)
    .filter(([k, v]) => v === '' && (numeric ? numeric.has(k) : NUMERIC_NAME.test(k)))
    .map(([k]) => k);
}
